const t = String(msg.topic || '');
const feed = t.split('/').pop().toLowerCase();
const map = {ph:'ph',temperature:'temperature',turbidity:'turbidity',ec:'ec',tds:'tds',do:'do'};
if (!map[feed]) return null;
const v = Number(typeof msg.payload === 'object' && msg.payload !== null && 'value' in msg.payload ? msg.payload.value : msg.payload);
if (!Number.isFinite(v)) return null;
msg.parameter = map[feed];
msg.value = v;
msg.timestamp = msg.timestamp || new Date().toISOString();
return msg;

const p = msg.parameter;
const ts = new Date(msg.timestamp);
if (!Number.isFinite(ts.getTime())) return null;
const hour = new Date(ts); hour.setUTCMinutes(0,0,0);
const key = hour.toISOString();
let buf = flow.get('hourly_buffer') || {};
buf[key] = buf[key] || {created_at:key, values:{}};
buf[key].values[p] = msg.value;
buf[key].received_at = new Date().toISOString();
const required=['ph','temperature','turbidity','ec','tds','do'];
const complete=required.every(k=>Number.isFinite(buf[key].values[k]));
if (!complete) { flow.set('hourly_buffer',buf); return null; }
if (buf[key].emitted) { flow.set('hourly_buffer',buf); return null; }
buf[key].emitted=true;
const rec={created_at:key,ph:buf[key].values.ph,temperature:buf[key].values.temperature,turbidity:buf[key].values.turbidity,ec:buf[key].values.ec,tds:buf[key].values.tds,do:buf[key].values.do};
// Keep only recent buffers.
const keys=Object.keys(buf).sort(); if(keys.length>48) delete buf[keys[0]];
flow.set('hourly_buffer',buf);
msg.payload=rec;
return msg;

const r=msg.payload;
const required=['created_at','ph','temperature','turbidity','ec','tds','do'];
const missing=required.filter(k=>!(k in r));
const nonNumeric=['ph','temperature','turbidity','ec','tds','do'].filter(k=>!Number.isFinite(Number(r[k])));
if(missing.length||nonNumeric.length){ msg.payload.validation_flag=1; msg.payload.flag_reason=`Schema:${missing.length?`missing=${missing.join(',')}`:''}${nonNumeric.length?` nonnumeric=${nonNumeric.join(',')}`:''}`; }
return msg;

const r=msg.payload;
const rules={ph:[0,14],temperature:[0,50],turbidity:[0,3000],ec:[0,5000],tds:[0,5000],do:[0,20]};
const reasons=[]; let flag=(r.validation_flag===1)?1:0;
for(const [k,[lo,hi]] of Object.entries(rules)){ const v=Number(r[k]); if(!Number.isFinite(v)||v<lo||v>hi){ reasons.push(`Stage1:${k}=${v} OOB[${lo},${hi}]`); flag=1; }}
r.validation_flag=flag; r.flag_reason=[r.flag_reason,...reasons].filter(Boolean).join('; ')||null;
return msg;

const r=msg.payload;
// pH, DO and turbidity limits are the values recorded in the deployed validation log (1.5, 3, 500).
// Temperature, EC and TDS limits are NOT recoverable from the log: the deployed pipeline accepted hourly changes of 2.29, 95.3 and 48.2, so replace these placeholders with the implemented values.
const limits={ph:1.5,temperature:2.5,turbidity:500,ec:150,tds:75,do:3};
const prev=flow.get('last_complete_record'); const reasons=[];
if(prev){
  const dt=(new Date(r.created_at)-new Date(prev.created_at))/3600000;
  r.temporal_gap_hours=dt;
  if(dt>=0.5 && dt<=1.5){
    for(const [k,lim] of Object.entries(limits)){ const d=Math.abs(Number(r[k])-Number(prev[k])); if(Number.isFinite(d)&&d>lim) reasons.push(`Stage2:${k}_ROC=${d.toFixed(3)}>${lim}/hr`); }
  } else if(dt>1.5){
    reasons.push(`TemporalGap:${dt.toFixed(1)}h`);
  }
}
if(reasons.some(x=>x.startsWith('Stage2:')) && r.validation_flag!==1) r.validation_flag=2;
r.flag_reason=[r.flag_reason,...reasons].filter(Boolean).join('; ')||null;
flow.set('last_complete_record',r);
return msg;

const r=msg.payload; const reasons=[];
if(Number(r.tds)>Number(r.ec)) reasons.push(`Stage3:TDS/EC=${(Number(r.tds)/Math.max(Number(r.ec),1e-9)).toFixed(3)} OOB`);
if(Number(r.ec)===0 && Number(r.tds)>0) reasons.push('Stage3:EC=0 with TDS>0');
if(reasons.length && r.validation_flag===0) r.validation_flag=2;
r.flag_reason=[r.flag_reason,...reasons].filter(Boolean).join('; ')||null;
return msg;

// Deployed behaviour (verified against the validation log): the mean and SD are taken over the 24 readings
// that PRECEDE the current record (current record excluded), so the check is causal and can run online.
let h=flow.get('trail24')||[]; const r=msg.payload; const features=['ph','temperature','turbidity','ec','tds','do']; const reasons=[];
if(h.length>=24){
  for(const f of features){const vals=h.slice(-24).map(x=>Number(x[f])).filter(Number.isFinite); if(vals.length<2) continue;
    const mean=vals.reduce((a,b)=>a+b,0)/vals.length; const sd=Math.sqrt(vals.reduce((a,b)=>a+(b-mean)**2,0)/(vals.length-1)); const v=Number(r[f]);
    if(sd>0 && Math.abs(v-mean)>3*sd) reasons.push(`Stage4:${f}=${v.toFixed(2)} ${(Math.abs(v-mean)/sd).toFixed(1)}σ>3σ mean=${mean.toFixed(2)}`);}
}
if(reasons.length && r.validation_flag===0) r.validation_flag=2;
r.flag_reason=[r.flag_reason,...reasons].filter(Boolean).join('; ')||null;
h.push({ph:r.ph,temperature:r.temperature,turbidity:r.turbidity,ec:r.ec,tds:r.tds,do:r.do}); if(h.length>48) h=h.slice(-48); flow.set('trail24',h);
msg.payload=r; return msg;

const r=msg.payload;
const c=flow.get('context_by_hour')||{}; const key=new Date(r.created_at); key.setUTCMinutes(0,0,0); const ctx=c[key.toISOString()]||{};
if(ctx.rainfall_mm_hr!==undefined) r.rainfall_mm_hr=ctx.rainfall_mm_hr;
if(ctx.maintenance!==undefined) r.maintenance=ctx.maintenance;
if(ctx.imperfection_type) r.imperfection_type=ctx.imperfection_type;
const environmental=Boolean(ctx.environmental_event || r.environmental_event);
const artifact=Boolean(r.imperfection_type);
let row_qc='VALID';
if(r.validation_flag===1) row_qc='INVALID_PARAMETER';
else if(environmental) row_qc='ENVIRONMENTAL_EVENT';
else if(r.validation_flag===2 || artifact) row_qc='SUSPECT';
r.environmental_event=environmental; r.row_qc=row_qc;
r.validation_flag=Number.isInteger(r.validation_flag)?r.validation_flag:0;
r.anomaly_event=false; r.alert=null;
msg.payload=r; msg.topic='owo-river/qc/record';
return msg;

let c=flow.get('context_by_hour')||{};
const p=(typeof msg.payload==='string')?JSON.parse(msg.payload):msg.payload;
if(!p || !p.created_at) return null;
const d=new Date(p.created_at); if(!Number.isFinite(d.getTime())) return null;
d.setUTCMinutes(0,0,0); const k=d.toISOString();
c[k]={rainfall_mm_hr:Number.isFinite(Number(p.rainfall_mm_hr))?Number(p.rainfall_mm_hr):null,environmental_event:Boolean(p.environmental_event),maintenance:Boolean(p.maintenance),imperfection_type:p.imperfection_type||null};
flow.set('context_by_hour',c);
return null;
